import 'dart:io';

import 'package:grund_generator/grund_generator.dart';
import 'package:path/path.dart' as p;

import '../cli/cli_exit_code.dart';
import '../cli/cli_failure.dart';
import '../package/package_root.dart';
import 'generated_outputs.dart';
import 'synced_files.dart';

/// Writes the generator's file set into a package: only the files whose
/// content changed, each through a temporary file and a rename (a reader
/// never sees a half-written file), never over a file the generator did
/// not write, and removing the generated files of an earlier run that the
/// new set no longer contains.
///
/// Every failure is a [CliFailure] with [CliExitCode.cannotCreate].
final class OutputWriter {
  /// Creates the writer for [package].
  const OutputWriter(this.package);

  /// The package written to.
  final PackageRoot package;

  /// Brings the generated files of the package to [files] (path relative
  /// to the package root to content).
  ///
  /// Nothing is written when one of the files would replace a file without
  /// the generator's header.
  SyncedFiles sync(Map<String, String> files) {
    final changes = <File, String>{};
    for (final MapEntry(key: path, value: content) in files.entries) {
      final target = _target(path);
      final existing = _read(target);
      if (existing == content) continue;
      if (existing != null) _checkGenerated(target, existing);
      changes[target] = content;
    }
    final stale = _stale({for (final path in files.keys) _target(path).path});
    changes.forEach(_replace);
    for (final file in stale) {
      _delete(file);
    }
    return SyncedFiles(
      written: _displayed(changes.keys),
      deleted: _displayed(stale),
      total: files.length,
    );
  }

  List<String> _displayed(Iterable<File> files) =>
      [for (final file in files) package.display(file.path)]..sort();

  /// The generated files under `lib/` that are not in [keep] (absolute
  /// paths).
  List<File> _stale(Set<String> keep) {
    final List<FileSystemEntity> entities;
    try {
      entities = Directory(
        package.libPath,
      ).listSync(recursive: true, followLinks: false);
    } on FileSystemException catch (error) {
      throw _cannotWrite(File(package.libPath), error);
    }
    return [
      for (final entity in entities)
        if (entity is File &&
            GeneratedOutputs.hasGeneratedName(entity.path) &&
            !keep.contains(entity.path) &&
            GeneratedOutputs.hasHeader(_read(entity) ?? ''))
          entity,
    ];
  }

  void _delete(File file) {
    try {
      file.deleteSync();
    } on FileSystemException catch (error) {
      throw _cannotWrite(file, error);
    }
  }

  File _target(String path) {
    final segments = p.posix.split(p.posix.normalize(path));
    final escapes =
        p.posix.isAbsolute(path) ||
        path.contains(r'\') ||
        segments.first == '..' ||
        RegExp(r'^[A-Za-z]:').hasMatch(segments.first);
    final target = File(p.joinAll([package.path, ...segments]));
    if (!escapes && p.isWithin(package.path, target.path)) return target;
    throw CliFailure(
      CliExitCode.cannotCreate,
      'Generated file "$path" is outside the package.',
    );
  }

  String? _read(File file) {
    try {
      return file.readAsStringSync();
    } on PathNotFoundException {
      return null;
    } on FileSystemException catch (error) {
      throw _cannotWrite(file, error);
    }
  }

  void _checkGenerated(File file, String content) {
    if (GeneratedOutputs.hasHeader(content)) return;
    throw CliFailure(
      CliExitCode.cannotCreate,
      '${package.display(file.path)} was not generated by grund '
      '(no "${LibraryWriter.header}" header); rename it, the generator '
      'owns this path.',
    );
  }

  void _replace(File target, String content) {
    final temporary = File('${target.path}.tmp');
    if (FileSystemEntity.typeSync(temporary.path, followLinks: false) !=
        FileSystemEntityType.notFound) {
      final shown = package.display(temporary.path);
      throw CliFailure(
        CliExitCode.cannotCreate,
        'Cannot write ${package.display(target.path)}: $shown exists; delete it if no other grund run is '
        'writing.',
      );
    }
    try {
      target.parent.createSync(recursive: true);
      temporary.writeAsStringSync(content, flush: true);
      temporary.renameSync(target.path);
    } on FileSystemException catch (error) {
      _discard(temporary);
      throw _cannotWrite(target, error);
    }
  }

  void _discard(File temporary) {
    try {
      if (temporary.existsSync()) temporary.deleteSync();
    } on FileSystemException {
      // The original error is the one reported.
    }
  }

  CliFailure _cannotWrite(File file, FileSystemException error) => CliFailure(
    CliExitCode.cannotCreate,
    'Cannot write ${package.display(file.path)}: '
    '${error.osError?.message ?? error.message}.',
  );
}
